  b: { x: [-1, 0, 0], y: [0, -1, 0], z: [0, 0, -1] },
  r: { x: [0, 0, -1], y: [0, -1, 0], z: [1, 0, 0] },
  l: { x: [0, 0, 1], y: [0, -1, 0], z: [-1, 0, 0] },
  u: { x: [1, 0, 0], y: [0, 0, 1], z: [0, 1, 0] },
